#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Sextante: one-time setup of Docker Hub, GitHub and ShardCloud (decisions 3.27 to 3.29 of
# docs/00, README "One-time setup"). Run from the repository root:
#   scripts/setup_shardcloud.sh
# ShardCloud is not called: its API answers automated clients with a Cloudflare challenge,
# so its steps are done in the dashboard, guided here. Secrets typed here go straight to
# GitHub; none is written to a file or put on a command line. Only non-secret values are
# kept, in config/.env.shardcloud (ignored by git), so a re-run resumes. It pushes nothing.
ENV_FILE="config/.env.shardcloud"

# ask_required KEY "Prompt" PATTERN [DEFAULT]: asks until the answer matches PATTERN.
# Enter takes DEFAULT (or the value saved by an earlier run). An empty value never goes
# on: `gh variable set` with an empty body silently waits for input.
ask_required() {
  local key="$1" prompt="$2" pattern="$3" fallback="${4:-}"
  while :; do
    if [[ -n "$fallback" && -z "$(_existing "$key" || true)" ]]; then
      ask "$key" "$prompt [Enter: $fallback]"
      [[ -z "${!key}" ]] && printf -v "$key" '%s' "$fallback"
    else
      ask "$key" "$prompt"
    fi
    [[ "${!key}" =~ $pattern ]] && return 0
    warn "Not valid: '${!key}'. Try again."
  done
}

# random_secret: a long random value.
random_secret() { python3 -c 'import secrets; print(secrets.token_urlsafe(32))'; }

run_wizard() {

TOTAL_STAGES=5

banner "Sextante: Docker Hub, GitHub and ShardCloud"

# ── 1 ────────────────────────────────────────────────────────────────────────
stage "Tools and GitHub login"
say "This wizard needs git, zip, python3 and the GitHub CLI (gh), logged in."
for tool in git zip python3; do
  command -v "$tool" >/dev/null 2>&1 || { warn "missing: $tool. Install it and run again."; exit 1; }
done
if ! command -v gh >/dev/null 2>&1; then
  warn "gh is not installed."
  open_url "https://github.com/cli/cli/blob/trunk/docs/install_linux.md"
  step "Install it as that page says for your distribution (Ubuntu: the apt repository)."
  pause "Press Enter once 'gh --version' works in another terminal."
  command -v gh >/dev/null 2>&1 || { warn "gh still missing. Run again after installing it."; exit 1; }
fi
if ! gh auth status >/dev/null 2>&1; then
  step "In another terminal run: gh auth login   (GitHub.com, HTTPS, log in with a web browser)."
  pause "Press Enter once 'gh auth status' says you are logged in."
fi
gh auth status >/dev/null 2>&1 || { warn "gh is not logged in. Run again after 'gh auth login'."; exit 1; }
REPO=$(gh repo view --json nameWithOwner --jq .nameWithOwner)
say "GitHub repository: ${BOLD}$REPO${RESET}"
note "Secrets and variables will be set there. If this is wrong, stop now (Ctrl-C)."
pause

# ── 2 ────────────────────────────────────────────────────────────────────────
stage "Docker Hub: private repository"
open_url "https://hub.docker.com/repositories"
step "Sign in, then Create a repository."
step "Name it (for example: sextante), set Visibility to Private, and Create."
ask_required DOCKERHUB_USERNAME "Your Docker Hub username:" '^[a-z0-9]{4,30}$'
ask_required DOCKERHUB_REPOSITORY "Repository, as <username>/<name>:" \
  '^[a-z0-9]{4,30}/[a-z0-9._-]+$' "$DOCKERHUB_USERNAME/sextante"
write_env DOCKERHUB_USERNAME "$DOCKERHUB_USERNAME"
write_env DOCKERHUB_REPOSITORY "$DOCKERHUB_REPOSITORY"
set_var DOCKERHUB_REPOSITORY "$DOCKERHUB_REPOSITORY"

# ── 3 ────────────────────────────────────────────────────────────────────────
stage "Docker Hub: access token for GitHub Actions"
open_url "https://app.docker.com/settings/personal-access-tokens"
step "Generate new token. Description: sextante GitHub Actions."
step "Access permissions: Read & Write. Generate, then copy the token (shown once)."
ask_secret DOCKERHUB_TOKEN "Paste the Docker Hub token (hidden):"
[[ -n "$DOCKERHUB_TOKEN" ]] || { warn "No token given."; exit 1; }
set_secret DOCKERHUB_USERNAME "$DOCKERHUB_USERNAME"
set_secret DOCKERHUB_TOKEN "$DOCKERHUB_TOKEN"
unset DOCKERHUB_TOKEN

# ── 4 ────────────────────────────────────────────────────────────────────────
stage "ShardCloud: the image"
build_dir=$(mktemp -d)
deploy/shardcloud/build_context.sh "$build_dir/context" HEAD setup
mkdir -p build
(cd "$build_dir/context" && zip -q -r -X - .) > build/sextante-setup.zip
rm -rf "$build_dir"
say "The build context is ready, Dockerfile at its root: $(pwd)/build/sextante-setup.zip"
note "Each release leaves the same kind of zip as its artifact sextante-X.Y.Z-shardcloud."
open_url "https://shardcloud.app/en"
step "Sign in and open Dashboard (your plan must be Core or higher)."
step "Custom Docker Images → create an image named sextante from that zip."
step "Wait until its build shows success."
pause "Press Enter once the image is built."

# ── 5 ────────────────────────────────────────────────────────────────────────
stage "ShardCloud: the application"
step "From the image, deploy an app named sextante with 2048 MB of RAM."
step "Turn on its web access with a subdomain (letters and digits only)."
step "In the app's environment variables, add these. Generated values are shown once:"
printf '\n      SEXTANTE_API_KEY=%s\n' "$(random_secret)"
printf '      SEXTANTE_ACCESS_TOKEN=%s   (what people type to sign in: keep it)\n' "$(random_secret)"
printf '      SEXTANTE_TARGET_ENTITY_NAME=Advanced Maritime Transports - Transitarios Limitada\n'
printf '      SEXTANTE_TARGET_ENTITY_NIF=<AMT tax number, as on its invoices>\n'
printf '      SEXTANTE_REVIEWER_ID=revisor-1\n'
printf '      SEXTANTE_ANTHROPIC_API_KEY=<a NEW key, typed straight into the dashboard>\n\n'
warn "Save SEXTANTE_ACCESS_TOKEN in your password manager; the screen is cleared next."
pause "Press Enter once the variables are saved and the app is running."
_clear
while :; do
  ask SHARDCLOUD_SUBDOMAIN "The app's address (e.g. sextante, or https://sextante.shardweb.app):"
  # The subdomain alone, whether typed bare, as a host or as an address.
  SHARDCLOUD_SUBDOMAIN="${SHARDCLOUD_SUBDOMAIN#http://}"
  SHARDCLOUD_SUBDOMAIN="${SHARDCLOUD_SUBDOMAIN#https://}"
  SHARDCLOUD_SUBDOMAIN="${SHARDCLOUD_SUBDOMAIN%%/*}"
  SHARDCLOUD_SUBDOMAIN="${SHARDCLOUD_SUBDOMAIN%.shardweb.app}"
  [[ "$SHARDCLOUD_SUBDOMAIN" =~ ^[A-Za-z0-9]{1,100}$ ]] && break
  warn "Not a shardweb.app address: type the subdomain, e.g. sextante."
done
SHARDCLOUD_URL="https://$SHARDCLOUD_SUBDOMAIN.shardweb.app"
write_env SHARDCLOUD_URL "$SHARDCLOUD_URL"
open_url "$SHARDCLOUD_URL/api/health"
step "Cloudflare hides the answer from terminals, so check it in the browser."
if ! confirm "Does the page show \"version\":\"setup\"?"; then
  warn "\"Site Não Encontrado\": turn on the app's web access with that subdomain."
  warn "Otherwise check the app's logs; if it expects a port other than 80, change"
  warn "deploy/shardcloud/nginx.conf."
fi

finish
say "Next, by you:"
step "Push the code: git push origin $(git branch --show-current), then merge into main."
step "Publish a version: git tag v1.0.0 && git push origin v1.0.0"
step "Upload the release's artifact sextante-X.Y.Z-shardcloud to ShardCloud (Rebuild), back up, Restart."
warn "Before real invoices: AMT confirms the data may stay at ShardCloud, and ShardCloud"
warn "confirms the app's files survive a redeploy (docs/00 §3.27)."
printf '\n'
}

run_wizard "$@"; exit
